function solveLinear(a,b){
  if(a===0){ return (b===0)?{type:'all'}:{type:'none'}; }
  return {type:'unique', x:-b/a};
}
function solveQuadratic(a,b,c){
  if(a===0) return {linear:true, sol: solveLinear(b,c)};
  var D=b*b-4*a*c;
  if(D>1e-9) return {type:'two', x1:(-b+Math.sqrt(D))/(2*a), x2:(-b-Math.sqrt(D))/(2*a), D:D};
  if(Math.abs(D)<=1e-9) return {type:'double', x:-b/(2*a), D:D};
  var re=-b/(2*a), im=Math.sqrt(-D)/(2*a);
  return {type:'complex', re:re, im:im, D:D};
}
